-- 043: 빌드 가이드 언어 분리 (한국어 가이드 / 영어 가이드)
--  - lang 컬럼: 'ko' | 'en'. 기존 가이드는 전부 'ko'. /en 에선 영어 가이드만, 한국어 주소에선 한국어 가이드만 보임
--  - 영어 가이드 15개 (한국어 가이드와 같은 내용, slug 는 뒤에 -en)
-- 여러 번 실행해도 됨 (영어 가이드는 slug 가 이미 있으면 건너뜀)

begin;

alter table public.tb_guide add column if not exists lang text not null default 'ko';
alter table public.tb_guide drop constraint if exists tb_guide_lang_check;
alter table public.tb_guide add constraint tb_guide_lang_check check (lang in ('ko', 'en'));
create index if not exists tb_guide_lang_idx on public.tb_guide (lang, created_at desc);

insert into public.tb_guide
  (slug, class_key, class_name, title, tier, description, summary, stat_priority,
   skill_order, key_items, leveling_notes, strengths, weaknesses, lang, created_at)
values
  ($g$g-sorc-fire-en$g$, $g$sorc$g$, $g$Sorceress$g$, $g$Fire Wall Sorceress — complete beginner guide$g$, $g$A TIER$g$, $g$Skill tree, gear and leveling order all in one$g$, $g$A fire Sorceress built around Fire Wall, with Fire Ball as backup. Fire Wall lays flames on the ground that burn monsters walking through, and putting points into Warmth and Inferno raises its damage.$g$, $g$Strength only for gear requirements, Dexterity only enough to reach max block with your shield (0 if you don't block), everything else into Vitality. You don't need Energy — mana comes from gear and Warmth.$g$,
   $g$[{"level":"1~11","skill":"Hunt with Fire Bolt, Warmth 1, Frozen Armor 1"},{"level":"12~17","skill":"Raise Fire Ball (prereq: Fire Bolt) + Inferno 1, Blaze 1 (Fire Wall prereq)"},{"level":"18~23","skill":"Keep raising Fire Ball, Telekinesis 1 → Teleport 1"},{"level":"24~29","skill":"Put points into Fire Wall first"},{"level":"30~","skill":"Fire Wall 20 → Fire Mastery 20"},{"level":"After that","skill":"Warmth · Inferno (Fire Wall synergies) → leftover points into Fire Ball"}]$g$::jsonb, $g$["Weapon & shield: Spirit (runeword) sword and shield — faster cast rate, mana, all skills","Helm: Harlequin Crest or a +Fire Skills circlet","Armor: Skin of the Vipermagi (faster cast rate, magic resist)","Gloves & belt: Magefist (faster cast rate, fire skills), Arachnid Mesh","Charms: +1 Fire Skills Grand Charm, life and resist Small Charms"]$g$::jsonb, $g$["Normal is fast enough with Fire Bolt → Fire Ball alone.","Lay Fire Wall across the path monsters take so they get hit several times. Teleport away to gain distance and pull them over the wall.","Hell has fire immune monsters. Skip them, or deal with them using your mercenary or a second elemental skill.","Hitting the 63% and 105% cast rate breakpoints makes a big difference — check with the breakpoint calculator."]$g$::jsonb, $g$["Area damage over time makes clearing packs fast","Low gear requirements make the early game easy"]$g$::jsonb, $g$["Weak against fire immune monsters","Dangerous when surrounded by melee monsters — Teleport is a must"]$g$::jsonb, 'en', $g$2026-09-15$g$::timestamptz),
  ($g$g-pal-hammer-en$g$, $g$paladin$g$, $g$Paladin$g$, $g$Hammerdin stat and skill order$g$, $g$S TIER$g$, $g$From solo farming to party support — tree variants for each situation$g$, $g$A Paladin who uses Blessed Hammer with the Concentration aura. Hammers deal magic damage, so few monsters resist them, and points in Vigor and Blessed Aim raise hammer damage.$g$, $g$Strength only for gear requirements, Dexterity only enough to reach max block with your shield, the rest into Vitality. Mana comes from gear (mana and mana leech).$g$,
   $g$[{"level":"1~17","skill":"Hunt in melee with Might and Zeal, Holy Bolt 1 (hammer prereq)"},{"level":"18","skill":"Blessed Hammer 1, Blessed Aim 1 → Concentration 1"},{"level":"18~","skill":"Blessed Hammer 20 first, then Concentration 20"},{"level":"24","skill":"Holy Shield 1 (prereq: Charge, Blessed Hammer)"},{"level":"After that","skill":"Vigor 20 → Blessed Aim 20 (hammer synergy)"}]$g$::jsonb, $g$["Weapon: Heart of the Oak or a Spirit sword","Shield: Spirit paladin shield or Stormshield","Armor: Enigma (Teleport) — otherwise Skin of the Vipermagi","Helm: Harlequin Crest","Ring & amulet: The Stone of Jordan, Mara's Kaleidoscope"]$g$::jsonb, $g$["Blessed Hammer spirals around the character, so dive in between the monsters.","It is magic damage, so only watch out for magic immune monsters.","Holy Shield greatly raises your block chance and defense.","Hitting the 75% and 125% cast rate breakpoints shortens the gap between hammers — check with the breakpoint calculator."]$g$::jsonb, $g$["Magic damage means few immune monsters","Holy Shield gives high block and defense, so you are sturdy"]$g$::jsonb, $g$["The hammer path makes killing distant enemies slow","Heavy mana cost — you need mana gear"]$g$::jsonb, 'en', $g$2026-09-14$g$::timestamptz),
  ($g$g-barb-wolf-en$g$, $g$barb$g$, $g$Barbarian$g$, $g$Whirlwind Barb vs Frenzy Barb — which one suits you?$g$, $g$A TIER$g$, $g$Whirlwind and Frenzy Barbarian compared, plus gear recommendations$g$, $g$A Whirlwind Barbarian spins and slashes through enemies, while a Frenzy Barbarian dual wields and hammers away. Both can raise party life and mana with Battle Orders.$g$, $g$Strength and Dexterity up to weapon requirements (Dexterity also helps attack rating), the rest into Vitality.$g$,
   $g$[{"level":"Whirlwind","skill":"Bash → Stun → Concentrate 1, Leap → Leap Attack 1 → Whirlwind 20 (from level 30)"},{"level":"Frenzy","skill":"Double Swing → Double Throw 1 → Frenzy 20 (from level 24)"},{"level":"Both","skill":"Shout 1 → Battle Orders · Battle Command, focus on one weapon mastery, Increased Speed · Natural Resistance"}]$g$::jsonb, $g$["Whirlwind weapon: Grief (Phase Blade etc.)","Frenzy weapons: two one-handed weapons (e.g. two Grief)","Armor: Fortitude or Enigma","Helm: Arreat's Face","Swap weapon: Call to Arms — boosts Battle Orders and Battle Command levels"]$g$::jsonb, $g$["Whirlwind needs level 30, so level with Bash and Double Swing until then.","Frenzy raises your movement and attack speed the more you hit enemies.","Swap to Call to Arms and use Battle Orders to greatly raise life and mana."]$g$::jsonb, $g$["Fast melee kills","Can buff the party with Battle Orders"]$g$::jsonb, $g$["Few ways to deal with ranged enemies","Heavily weapon dependent"]$g$::jsonb, 'en', $g$2026-09-12$g$::timestamptz),
  ($g$g-necro-bone-en$g$, $g$necro$g$, $g$Necromancer$g$, $g$Bone Necro leveling route — Normal to Hell$g$, $g$A TIER$g$, $g$When to switch from Bone Spear to Bone Spirit$g$, $g$A Necromancer who fights with Bone Spear and Bone Spirit. Teeth, Bone Wall and Bone Prison are synergies for Bone Spear and Bone Spirit, and bone skills deal magic damage, so immunities are rarely a problem.$g$, $g$Strength only for gear requirements, Dexterity for blocking with a shield (optional), the rest into Vitality.$g$,
   $g$[{"level":"1~17","skill":"Hunt with Teeth, Amplify Damage 1, Bone Armor 1, Corpse Explosion 1"},{"level":"18~29","skill":"Raise Bone Spear (prereq: Corpse Explosion)"},{"level":"30~","skill":"Bone Spirit (prereq: Bone Spear)"},{"level":"After that","skill":"Bone Spear · Bone Spirit 20 → Teeth · Bone Wall · Bone Prison (synergies)"}]$g$::jsonb, $g$["Weapon: a wand with bone skills or Wizardspike","Shield: Homunculus or a Necromancer shield with +Bone Skills","Helm: Harlequin Crest","Armor: Enigma or Skin of the Vipermagi"]$g$::jsonb, $g$["Early in Normal, it is fine to let Raise Skeleton hold the line in front of you.","Bone Spear pierces in a straight line, so line monsters up and fire.","Bone Spirit chases enemies and hits them, which makes it good against bosses and single targets."]$g$::jsonb, $g$["Magic damage means few immune monsters","Bone Prison and Bone Wall block paths, so you stay safe"]$g$::jsonb, $g$["Slow against wide, scattered packs","Heavy mana cost — you need mana gear"]$g$::jsonb, 'en', $g$2026-09-10$g$::timestamptz),
  ($g$g-amazon-bow-en$g$, $g$amazon$g$, $g$Amazon$g$, $g$Multishot Bowazon — ranged area farming$g$, $g$A TIER$g$, $g$A bow build that sweeps corridors with a fan of arrows$g$, $g$A bow Amazon who clears packs with Multiple Shot and kills bosses with Guided Arrow. Critical Strike, Penetrate and Pierce make up for damage and attack rating.$g$, $g$Strength only for gear requirements, mostly Dexterity (bow damage and attack rating), the rest into Vitality.$g$,
   $g$[{"level":"1~17","skill":"Hunt with Magic Arrow and Cold Arrow, Multiple Shot (from level 6)"},{"level":"18~","skill":"Guided Arrow (prereq: Cold Arrow, Multiple Shot), Critical Strike · Penetrate"},{"level":"30~","skill":"Valkyrie 1 (prereq: Decoy, Evade), Pierce"},{"level":"After that","skill":"Multiple Shot · Guided Arrow 20 → Critical Strike · Penetrate"}]$g$::jsonb, $g$["Bow: Windforce or Lycander's Aim (Buriza-Do Kyanon for a crossbow)","Helm: Harlequin Crest","Armor: Enigma or Fortitude","Gloves & belt: increased attack speed (IAS) stats"]$g$::jsonb, $g$["Level early on with Magic Arrow so you never worry about mana.","Switching between Multiple Shot for packs and Guided Arrow for bosses is the efficient way to play.","Valkyrie holds the line in front of you, which makes survival much easier."]$g$::jsonb, $g$["Attack from a safe distance","Handles both area and single target"]$g$::jsonb, $g$["Low survivability when enemies get close","Heavily bow gear dependent"]$g$::jsonb, 'en', $g$2026-09-08$g$::timestamptz),
  ($g$g-druid-wind-en$g$, $g$druid$g$, $g$Druid$g$, $g$Hurricane Wind Druid — sustained area damage$g$, $g$A TIER$g$, $g$An elemental Druid that fills the screen with Tornado and Hurricane$g$, $g$An elemental Druid who uses Hurricane (cold) and Tornado (physical) together. Twister, Tornado and Hurricane synergize with each other, and Cyclone Armor absorbs elemental damage.$g$, $g$Strength only for gear requirements, Dexterity for blocking with a shield (optional), the rest into Vitality.$g$,
   $g$[{"level":"1~17","skill":"Hunt with Firestorm and Arctic Blast, Cyclone Armor 1"},{"level":"18","skill":"Twister 1"},{"level":"24~","skill":"Tornado (prereq: Twister)"},{"level":"30~","skill":"Hurricane 20 (prereq: Tornado)"},{"level":"After that","skill":"Tornado 20 → Twister · Cyclone Armor (synergies), Oak Sage 1"}]$g$::jsonb, $g$["Weapon: Heart of the Oak or a weapon with +Elemental Skills","Helm: Jalal's Mane or a Druid helm with +Elemental Skills","Armor: Enigma or Skin of the Vipermagi","Ring: The Stone of Jordan"]$g$::jsonb, $g$["Hurricane is a cold storm that circles the character, so you have to step in among the enemies — always keep Cyclone Armor on.","Handle cold immune monsters with Tornado (physical)."]$g$::jsonb, $g$["Two damage types (cold and physical) cover immunities","Cyclone Armor makes you resistant to elemental damage"]$g$::jsonb, $g$["Weak against monsters immune to both cold and physical","Heavy mana cost"]$g$::jsonb, 'en', $g$2026-09-06$g$::timestamptz),
  ($g$g-assassin-trap-en$g$, $g$assassin$g$, $g$Assassin$g$, $g$Trapsin — wiping packs with Lightning Sentry$g$, $g$A TIER$g$, $g$A ranged, support-style build that deals damage safely with placed traps$g$, $g$A trap Assassin who lays down Lightning Sentries and finishes with Death Sentry (corpse explosion). Shock Web and Charged Bolt Sentry are synergies for Lightning Sentry.$g$, $g$Strength and Dexterity only for gear requirements, the rest into Vitality.$g$,
   $g$[{"level":"1~11","skill":"Hunt mainly with Fire Blast"},{"level":"12~23","skill":"Charged Bolt Sentry, Shock Web"},{"level":"24~","skill":"Lightning Sentry 20 (prereq: Charged Bolt Sentry)"},{"level":"30~","skill":"Death Sentry (prereq: Lightning Sentry)"},{"level":"After that","skill":"Shock Web · Charged Bolt Sentry (synergies), Fade · Shadow Master 1"}]$g$::jsonb, $g$["Weapon: an Assassin claw with trap skills","Helm: Harlequin Crest","Armor: Enigma or Skin of the Vipermagi","Shield: Stormshield or Spirit","Belt: Arachnid Mesh"]$g$::jsonb, $g$["You can place up to 5 sentries at once — group them along the path monsters take.","Death Sentry needs a corpse to explode. Kill something with Lightning Sentry first, then place it.","Handle lightning immune monsters with Death Sentry or your mercenary."]$g$::jsonb, $g$["Attack from a safe distance","Fast single target boss kills"]$g$::jsonb, $g$["Weak against lightning immune monsters","Not enough room to place sentries in tight spaces"]$g$::jsonb, 'en', $g$2026-09-04$g$::timestamptz),
  ($g$g-warlock-summon-en$g$, $g$warlock$g$, $g$Warlock$g$, $g$Demon tree Summoner Warlock — new class starter guide$g$, $g$B TIER$g$, $g$A starter build for the new class, with Goatman, Tainted and Defiler up front and field demons bound as well$g$, $g$The Warlock, a new class added with the "Reign of the Warlock" DLC, has three skill trees: Chaos, Eldritch and Demon. This guide is the basic Demon tree build: summons in front, with the Warlock's own tools — Bind Demon and Consume — for improvising mid-fight.$g$, $g$Invest mainly in Vitality and add Strength only up to gear requirements. Early on, when you rely heavily on summons, survival comes first.$g$,
   $g$[{"level":"1~20","skill":"Summon Goatman 20 (main summon)"},{"level":"21~30","skill":"Demonic Mastery 10 (2 summons) → 20 (3 summons). Demons absorbed with Consume count toward this number"},{"level":"31~40","skill":"Spread points across Summon Tainted and Summon Defiler (summon variety)"},{"level":"41~","skill":"Death Mark, Bind Demon. 10 hard points can bind a Champion, 15 a Unique, 20 a Super Unique (3.2)"},{"level":"After that","skill":"Finish with self-buff skills: Blood Oath · Engorge · Blood Boil · Consume"}]$g$::jsonb, $g$["Offhand: Grimoire (Warlock only) — to hold a two-handed weapon in one hand, you need a Grimoire in the other (3.2)","Armor: mostly maximum life and elemental resists","Ring & amulet: mana recovery and resists","Weapon: a dagger, or consider a runeword with Warlock skills"]$g$::jsonb, $g$["The core of the Warlock is Bind Demon — you bind demon monsters in the field and borrow their abilities. Since 3.2, elite demons can only be bound if you have hard points in Bind Demon.","Absorbing a demon with Consume gives you a buff. Since 3.2, the higher the difficulty that demon came from, the bigger the bonus (Hell > Nightmare > Normal).","Since 3.2, life potions are 150% as effective, which makes early survival easier."]$g$::jsonb, $g$["Play safely with summons up front","Bind and Consume let you adapt mid-fight"]$g$::jsonb, $g$["A learning curve before you get used to managing summons","Binding elite demons takes many points in Bind Demon"]$g$::jsonb, 'en', $g$2026-09-29$g$::timestamptz),
  ($g$g-sorc-blizzard-en$g$, $g$sorc$g$, $g$Sorceress$g$, $g$Blizzard Sorceress — the standard season starter$g$, $g$A TIER$g$, $g$A cold Sorceress that grows well on little gear, the safest pick for a season start$g$, $g$A cold Sorceress who freezes and kills over a wide area with Blizzard, and uses Glacial Spike to freeze and hit between Blizzard cooldowns. Blizzard gets stronger the more points you put into Ice Bolt, Ice Blast and Glacial Spike.$g$, $g$Strength only for gear requirements, Dexterity only enough to reach max block with your shield (0 if you don't block), the rest into Vitality. Mana comes from gear and mercenary auras.$g$,
   $g$[{"level":"1~17","skill":"Hunt with Ice Bolt and Frost Nova, Frozen Armor 1, Static Field 1"},{"level":"18~23","skill":"Glacial Spike (prereq: Ice Blast), Telekinesis 1 → Teleport 1"},{"level":"24~29","skill":"Put points into Blizzard first (prereq: Frost Nova, Glacial Spike)"},{"level":"30~","skill":"Blizzard 20 → Cold Mastery (lowers cold resistance of enemies that are not cold immune)"},{"level":"After that","skill":"Glacial Spike 20 → Ice Blast · Ice Bolt (Blizzard synergies)"}]$g$::jsonb, $g$["Weapon & shield: Spirit (sword and shield) or Heart of the Oak","Helm: Harlequin Crest","Armor: Enigma or Skin of the Vipermagi (Stealth early on)","Gloves: Magefist","Belt: Arachnid Mesh","Amulet: Mara's Kaleidoscope","Ring: The Stone of Jordan","Mercenary: Act 2 mercenary + Insight (mana regeneration)"]$g$::jsonb, $g$["Blizzard has a cooldown — freeze enemies with Glacial Spike in between so you aren't just standing there taking hits.","Deal with cold immune monsters using your mercenary or Static Field, or skip them.","Hitting the 63% and 105% cast rate breakpoints makes a big difference — check with the breakpoint calculator."]$g$::jsonb, $g$["Strong on little gear, so great for a season start","Wide area attacks and freezing keep you safe"]$g$::jsonb, $g$["Weak against cold immune monsters","The Blizzard cooldown makes single targets slower"]$g$::jsonb, 'en', $g$2026-09-19$g$::timestamptz),
  ($g$g-sorc-lightning-en$g$, $g$sorc$g$, $g$Sorceress$g$, $g$Lightning Sorceress — Terror Zone farming$g$, $g$A TIER$g$, $g$A lightning Sorceress that bounces Chain Lightning through packs of monsters$g$, $g$A lightning Sorceress who uses Chain Lightning as the main attack and Lightning for single targets. Chain Lightning gets stronger the more points you put into Charged Bolt, Lightning and Nova, and it is more efficient the more monsters there are.$g$, $g$Strength only for gear requirements, Dexterity only enough to reach max block with your shield (0 if you don't block), the rest into Vitality.$g$,
   $g$[{"level":"1~11","skill":"Hunt with Charged Bolt, Static Field 1, Frozen Armor 1"},{"level":"12~17","skill":"Lightning (prereq: Charged Bolt), Nova 1 (prereq: Static Field)"},{"level":"18~23","skill":"Put points into Chain Lightning first (prereq: Lightning), Telekinesis 1 → Teleport 1"},{"level":"24~29","skill":"Energy Shield 1 (prereq: Teleport, Chain Lightning)"},{"level":"30~","skill":"Chain Lightning 20 → Lightning Mastery 20"},{"level":"After that","skill":"Lightning · Charged Bolt (Chain Lightning synergies)"}]$g$::jsonb, $g$["Helm: Griffon's Eye (lowers enemy lightning resistance)","Weapon & shield: Spirit (sword and shield) or Heart of the Oak","Armor: Enigma or Skin of the Vipermagi","Gloves: Magefist","Belt: Arachnid Mesh","Ring: The Stone of Jordan","Mercenary: Act 2 mercenary + Infinity (Conviction aura breaks lightning immunity)"]$g$::jsonb, $g$["Lightning immune monsters can only be killed with the Conviction aura from an Infinity mercenary — skip them until then.","Chain Lightning bounces between monsters, so fire it into the middle of a pack.","Hitting the 63% and 105% cast rate breakpoints makes a big difference."]$g$::jsonb, $g$["Very fast kills where monsters are many (Terror Zones)","Teleport makes getting around quick"]$g$::jsonb, $g$["Weak against lightning immune monsters before an Infinity mercenary","Damage varies a lot, so single targets are inconsistent"]$g$::jsonb, 'en', $g$2026-09-20$g$::timestamptz),
  ($g$g-amazon-javazon-en$g$, $g$amazon$g$, $g$Amazon$g$, $g$Lightning Fury Amazon — javelin area damage$g$, $g$A TIER$g$, $g$A javelin Amazon that clears packs with Lightning Fury and bosses with Charged Strike$g$, $g$A javelin Amazon who throws Lightning Fury to clear packs and kills melee bosses with Charged Strike. Lightning Fury gets stronger the more points you put into Charged Strike, Lightning Bolt, Power Strike and Lightning Strike.$g$, $g$Strength only for gear requirements, Dexterity moderately for attack rating, the rest into Vitality.$g$,
   $g$[{"level":"1~5","skill":"Hunt with Jab"},{"level":"6~11","skill":"Power Strike (prereq: Jab), Poison Javelin 1"},{"level":"12~17","skill":"Lightning Bolt 1 (prereq: Poison Javelin), Dodge · Avoid 1"},{"level":"18~29","skill":"Charged Strike (prereq: Power Strike, Lightning Bolt), Plague Javelin 1 (prereq: Lightning Bolt)"},{"level":"30~","skill":"Lightning Fury 20 (prereq: Plague Javelin), Lightning Strike 1 (prereq: Charged Strike), Valkyrie 1 (prereq: Decoy, Evade)"},{"level":"After that","skill":"Charged Strike 20 → Lightning Bolt · Power Strike · Lightning Strike (synergies)"}]$g$::jsonb, $g$["Weapon: Titan's Revenge or Thunderstroke (javelin)","Shield: Lidless Wall or Spirit","Helm: Griffon's Eye","Armor: Enigma or Chains of Honor","Belt: Arachnid Mesh","Mercenary: Act 2 mercenary + Infinity (breaks lightning immunity)"]$g$::jsonb, $g$["Lightning Fury spreads lightning around the monster it hits — aim at the middle of a pack.","Charged Strike is a melee attack, so it is good for killing a single boss.","Skip lightning immune monsters if you don't have an Infinity mercenary."]$g$::jsonb, $g$["Very fast pack clearing","Has attacks for both packs and bosses"]$g$::jsonb, $g$["Weak against lightning immune monsters before an Infinity mercenary","Heavily dependent on javelin gear (Titan's Revenge etc.)"]$g$::jsonb, 'en', $g$2026-09-21$g$::timestamptz),
  ($g$g-necro-summon-en$g$, $g$necro$g$, $g$Necromancer$g$, $g$Summoner Necromancer — staying safe with a skeleton army$g$, $g$A TIER$g$, $g$A summoner Necro that puts Skeleton Warriors, Skeletal Mages and Golems up front and cleans up with Corpse Explosion$g$, $g$You summon Skeleton Warriors and Skeletal Mages to fight for you, while the Necromancer helps with curses and Corpse Explosion. Even with little gear, the skeletons take the hits for you, so leveling is safe.$g$, $g$Strength only for gear requirements, Dexterity for blocking with a shield (optional), the rest into Vitality.$g$,
   $g$[{"level":"1~5","skill":"Raise Skeleton · Skeleton Mastery, Amplify Damage 1"},{"level":"6~11","skill":"Clay Golem 1, Corpse Explosion 1 (prereq: Teeth)"},{"level":"12~23","skill":"Raise Skeletal Mage 1 (prereq: Raise Skeleton), Golem Mastery 1 (prereq: Clay Golem)"},{"level":"24~","skill":"Summon Resist (prereq: Golem Mastery), Decrepify 1 (prereq: Weaken → Terror)"},{"level":"After that","skill":"Raise Skeleton 20 → Skeleton Mastery 20 → Summon Resist, then Corpse Explosion if there is anything left"}]$g$::jsonb, $g$["Shield: Homunculus or Spirit","Helm: Harlequin Crest","Armor: Enigma or Skin of the Vipermagi","Weapon: Arm of King Leoric or a wand with +Summoning Skills","Mercenary: Act 2 mercenary + Insight"]$g$::jsonb, $g$["Skeletons need corpses to be raised — keep refilling them from the monsters you kill.","Clear packs in one go with the Amplify Damage curse + Corpse Explosion.","Decrepify is good against bosses (slows them and reduces their damage)."]$g$::jsonb, $g$["The skeletons take the hits, so you stay safe","Can start with little gear"]$g$::jsonb, $g$["Kills are slower than elemental builds","In narrow paths the skeletons block the way"]$g$::jsonb, 'en', $g$2026-09-22$g$::timestamptz),
  ($g$g-pal-smiter-en$g$, $g$paladin$g$, $g$Paladin$g$, $g$Smiter Paladin — Uber Tristram specialist$g$, $g$A TIER$g$, $g$A shield Paladin that kills Uber bosses with Smite, which always hits$g$, $g$A single target Paladin who bashes with the shield using Smite (always hits) at high speed through the Fanaticism aura. It specializes in strong single targets such as Uber Tristram and Uber bosses rather than pack farming.$g$, $g$Strength only for gear requirements, Dexterity only enough to reach max block with your shield, the rest into Vitality.$g$,
   $g$[{"level":"1~11","skill":"Level with Sacrifice 1, Smite and Might"},{"level":"12~23","skill":"Charge 1 (prereq: Smite), hunt with Zeal (prereq: Sacrifice), Blessed Aim 1"},{"level":"24~29","skill":"Holy Bolt · Blessed Hammer 1 → Holy Shield 1 (prereq: Charge, Blessed Hammer)"},{"level":"30~","skill":"Concentration 1 → Fanaticism 1 (prereq: Concentration)"},{"level":"After that","skill":"Smite 20 → Fanaticism 20 → Holy Shield 20 → resist auras"}]$g$::jsonb, $g$["Weapon: Grief (Phase Blade etc.)","Shield: Herald of Zakarum","Helm: Guillaume's Face","Armor: Fortitude","Gloves: Dracul's Grasp","Ring: Raven Frost (cannot be frozen)","Mercenary: Act 2 mercenary + Insight or Infinity"]$g$::jsonb, $g$["Smite always hits, so you don't have to worry about attack rating.","Against Uber Mephisto and Baal, cannot be frozen (Raven Frost) and resists are a must.","Pack hunting is slow, so share farming with other builds."]$g$::jsonb, $g$["Very strong against strong single targets (always hits)","Holy Shield gives a high block chance, so you are sturdy"]$g$::jsonb, $g$["Slow at killing packs","Heavily dependent on gear such as Grief and Dracul's Grasp"]$g$::jsonb, 'en', $g$2026-09-23$g$::timestamptz),
  ($g$g-warlock-echo-en$g$, $g$warlock$g$, $g$Warlock$g$, $g$Echoing Strike Warlock — two-handed weapon burst damage$g$, $g$A TIER$g$, $g$An Eldritch tree Warlock that throws echoes of a two-handed weapon to cut through packs and bosses alike$g$, $g$An Eldritch tree build that sends out echoes of your weapon with Echoing Strike, piercing and cutting through packs. Echoing Strike uses weapon damage (90% since 3.2) and gets stronger the more points you put into Mirrored Blades and Blade Warp. You need Levitation Mastery to hold a two-handed weapon together with a Grimoire.$g$, $g$Strength up to weapon requirements, Dexterity moderately for attack rating, the rest into Vitality.$g$,
   $g$[{"level":"1~5","skill":"Levitation Mastery 1 (two-handed weapon + Grimoire)"},{"level":"6~11","skill":"Hunt with Cleave (prereq: Levitation Mastery)"},{"level":"12~17","skill":"Put points into Echoing Strike first (prereq: Levitation Mastery)"},{"level":"18~23","skill":"Blade Warp 1 (prereq: Echoing Strike, movement skill), Psychic Ward 1 (prereq: Cleave)"},{"level":"24~29","skill":"Eldritch Blast 1 (prereq: Mind Ward)"},{"level":"30~","skill":"Mirrored Blades 1 (prereq: Blade Warp, Eldritch Blast), Echoing Strike 20"},{"level":"After that","skill":"Mirrored Blades · Blade Warp 20 (synergies) → Levitation Mastery"}]$g$::jsonb, $g$["Weapon: a two-handed weapon with high base damage","Offhand: Grimoire (required to hold a two-handed weapon in one hand, 3.2)","Armor: Enigma or Chains of Honor","Helm: Harlequin Crest","Belt: Arachnid Mesh","Mercenary: Act 2 mercenary + Insight"]$g$::jsonb, $g$["Since 3.2, to hold a two-handed weapon in one hand you need a Grimoire in the other hand (a shield won't do).","Blade Warp is your main movement skill until you get Enigma (Teleport).","It uses weapon damage as is, so your damage changes a lot every time you swap weapons."]$g$::jsonb, $g$["Very high damage against both packs and bosses","Blade Warp makes getting around fast"]$g$::jsonb, $g$["Heavily weapon dependent","Busy to play"]$g$::jsonb, 'en', $g$2026-09-24$g$::timestamptz),
  ($g$g-warlock-fire-en$g$, $g$warlock$g$, $g$Warlock$g$, $g$Fire Warlock — the fastest leveling$g$, $g$A TIER$g$, $g$A Chaos tree Warlock that pushes through Normal and Nightmare fast with Ring of Fire and Flame Wave$g$, $g$A Chaos tree fire build that sweeps the way ahead with Flame Wave and burns everything around you with Ring of Fire. Flame Wave gets stronger the more points you put into Ring of Fire and Apocalypse, and you add Apocalypse from level 30. Damage was reduced in 3.2, but leveling speed is still fast.$g$, $g$Strength only for gear requirements, the rest into Vitality.$g$,
   $g$[{"level":"1~5","skill":"Hunt with Miasma Bolt"},{"level":"6~17","skill":"Ring of Fire (no prereq), Sigil: Lethargy 1"},{"level":"18~23","skill":"Put points into Flame Wave first (prereq: Ring of Fire), Sigil: Rancor 1 (prereq: Sigil: Lethargy)"},{"level":"24~29","skill":"Sigil: Death 1 (prereq: Sigil: Rancor)"},{"level":"30~","skill":"Apocalypse (prereq: Flame Wave, Sigil: Death)"},{"level":"After that","skill":"Flame Wave 20 → Ring of Fire · Apocalypse (synergies)"}]$g$::jsonb, $g$["Weapon: Spirit or Heart of the Oak (faster cast rate, all skills)","Offhand: Grimoire","Helm: Harlequin Crest","Armor: Enigma or Skin of the Vipermagi","Gloves: Magefist","Belt: Arachnid Mesh","Mercenary: Act 2 mercenary + Infinity (Conviction aura breaks fire immunity)"]$g$::jsonb, $g$["Normal and Nightmare are fast enough with Flame Wave alone.","In Hell, fire immune monsters can only be killed with an Infinity mercenary.","Hitting the 75% and 125% cast rate breakpoints makes a big difference (same table as the Necromancer)."]$g$::jsonb, $g$["Very fast leveling","Can start with little gear"]$g$::jsonb, $g$["Weak against fire immune monsters in Hell","The 3.2 nerf leaves late game damage lower than other builds"]$g$::jsonb, 'en', $g$2026-09-25$g$::timestamptz)
